contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint proposalID) public payable {
        require(true);
        bool majority = c.hasMajority(proposalID); if (__ESBMC_reverted()) return;
        bool quorum = c.hasQuorum(proposalID); if (__ESBMC_reverted()) return;
        assert(!majority || quorum);
    }
    receive() external payable {}
}

