pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DAO c;

    function setUp() public {
        c = new DAO();
    }

    function _run(uint256 proposalID) internal {
        vm.assume(true);
        bool majority;
        try c.hasMajority(proposalID) returns (bool __r) { majority = __r; } catch { return; }
        bool quorum;
        try c.hasQuorum(proposalID) returns (bool __r) { quorum = __r; } catch { return; }
        assertTrue(!majority || quorum);
    }

    function testFuzz_run(uint256 proposalID) public {
        _run(proposalID);
    }

    receive() external payable {}
}
